function normalized(token: string): string {
  return token.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

export function translateCatalogName(source: string, lang: Lang): string {
  if (lang !== 'fr') return source;
  let text = source;
  const phrases = Object.keys(PHRASES).sort((a, b) => b.length - a.length);
  for (const phrase of phrases) {
    const escaped = phrase.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    text = text.replace(new RegExp(escaped, 'gi'), PHRASES[phrase]![lang]);
  }
  const replacementByWord = new Map([...Object.entries(WORDS), ...Object.entries(EXTRA_WORDS)].map(([key, value]) => [normalized(key), value[lang]]));
  return text.replace(/[A-Za-zÀ-ÿ]+/g, (token) => {
    const replacement = replacementByWord.get(normalized(token));
    if (!replacement) return token;
    return token.toUpperCase() === token ? replacement.toUpperCase() : replacement;
  }).replace(/\s+/g, ' ').trim();
}
